class Solution {
    public int findMin(int[] nums) {
        int left = 0, right = nums.length - 1;

        while (left < right) {
            int mid = left + (right - left) / 2;

            if (nums[mid] > nums[right]) {
                // 最小值在右半部分
                left = mid + 1;
            } else {
                // 最小值在左半部分（包含 mid）
                right = mid;
            }
        }

        return nums[left];
    }
}

class Solution {
    public int findMin(int[] nums) {
        int n = nums.length;

        // 未旋转或只有一个元素
        if (n == 1 || nums[0] < nums[n - 1]) {
            return nums[0];
        }

        int left = 0, right = n - 1;

        while (left < right) {
            int mid = left + (right - left) / 2;

            // 找到旋转点
            if (nums[mid] > nums[mid + 1]) {
                return nums[mid + 1];
            }
            if (mid > 0 && nums[mid - 1] > nums[mid]) {
                return nums[mid];
            }

            if (nums[mid] > nums[0]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return nums[left];
    }
}
